definition.script:
var arrayInput = input.get('array');
var operation = input.get('operation') || 'count';
var propertyPath = input.get('propertyPath') || '';
var filterValue = input.get('filterValue') || '';
var filterOperator = input.get('filterOperator') || 'equals';
var sortOrder = input.get('sortOrder') || 'asc';
var sliceStart = parseInt(input.get('sliceStart') || '0');
var sliceEnd = input.get('sliceEnd') ? parseInt(input.get('sliceEnd')) : null;

if (!arrayInput) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'Array input is required');
    output.set('Result', '[]');
    tags.trigger('error');
} else {
    try {
        var arr = json.parse(arrayInput);
        if (!Array.isArray(arr)) {
            throw new Error('Input must be a JSON array');
        }

        function getVal(obj, path) {
            if (!path) return obj;
            var parts = path.split('.');
            var val = obj;
            for (var i = 0; i < parts.length; i++) {
                if (val === null || val === undefined) return undefined;
                val = val[parts[i]];
            }
            return val;
        }

        var result = arr;
        var originalCount = arr.length;

        switch (operation) {
            case 'filter':
                result = arr.filter(function(item) {
                    var val = getVal(item, propertyPath);
                    var cmp = filterValue;
                    if (!isNaN(parseFloat(cmp)) && cmp !== '') cmp = parseFloat(cmp);
                    if (cmp === 'true') cmp = true;
                    if (cmp === 'false') cmp = false;
                    if (cmp === 'null') cmp = null;

                    switch (filterOperator) {
                        case 'equals': return val == cmp;
                        case 'notEquals': return val != cmp;
                        case 'contains': return String(val).indexOf(String(cmp)) >= 0;
                        case 'startsWith': return String(val).indexOf(String(cmp)) === 0;
                        case 'endsWith': return String(val).slice(-String(cmp).length) === String(cmp);
                        case 'greaterThan': return val > cmp;
                        case 'lessThan': return val < cmp;
                        case 'exists': return val !== undefined && val !== null;
                        case 'notExists': return val === undefined || val === null;
                        default: return val == cmp;
                    }
                });
                break;

            case 'map':
                if (propertyPath) {
                    result = arr.map(function(item) {
                        return getVal(item, propertyPath);
                    });
                }
                break;

            case 'sort':
                result = arr.slice().sort(function(a, b) {
                    var valA = propertyPath ? getVal(a, propertyPath) : a;
                    var valB = propertyPath ? getVal(b, propertyPath) : b;
                    if (valA === valB) return 0;
                    if (valA === null || valA === undefined) return 1;
                    if (valB === null || valB === undefined) return -1;
                    var cmp = valA < valB ? -1 : 1;
                    return sortOrder === 'desc' ? -cmp : cmp;
                });
                break;

            case 'dedupe':
                var seen = {};
                result = arr.filter(function(item) {
                    var val = propertyPath ? getVal(item, propertyPath) : item;
                    var key = typeof val === 'object' ? json.stringify(val) : String(val);
                    if (seen[key]) return false;
                    seen[key] = true;
                    return true;
                });
                break;

            case 'flatten':
                result = [];
                function flattenArr(a) {
                    for (var i = 0; i < a.length; i++) {
                        if (Array.isArray(a[i])) {
                            flattenArr(a[i]);
                        } else {
                            result.push(a[i]);
                        }
                    }
                }
                flattenArr(arr);
                break;

            case 'reverse':
                result = arr.slice().reverse();
                break;

            case 'slice':
                var end = sliceEnd !== null ? sliceEnd : arr.length;
                result = arr.slice(sliceStart, end);
                break;

            case 'first':
                result = arr.length > 0 ? [arr[0]] : [];
                break;

            case 'last':
                result = arr.length > 0 ? [arr[arr.length - 1]] : [];
                break;

            case 'count':
            default:
                break;
        }

        output.set('Result', json.stringify(result));
        output.set('ResultArray', result);
        output.set('Count', result.length);
        output.set('OriginalCount', originalCount);
        output.set('First', result.length > 0 ? json.stringify(result[0]) : '');
        output.set('Last', result.length > 0 ? json.stringify(result[result.length - 1]) : '');
        output.set('IsEmpty', result.length === 0);
        output.set('HasErrors', false);
        output.set('ErrorMessage', '');

        log.info(operation + ': ' + originalCount + ' -> ' + result.length + ' items');
        tags.trigger('success');

    } catch (ex) {
        log.error('Array operation failed: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        output.set('Result', '[]');
        tags.trigger('error');
    }
}
